#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>

using namespace std;

vector<int> strToIntArr(const string& s) {
    vector<int> retArr;
    size_t start = 0, end = 0;
    while ((end = s.find(' ', start)) != string::npos) {
        string token = s.substr(start, end - start);
        retArr.push_back(stoi(token));
        start = end + 1;
    }
    // last token
    if (start < s.size()) {
        retArr.push_back(stoi(s.substr(start)));
    }
    return retArr;
}

bool checkSub(const vector<int>& aArr, int splitInd) {
    int nEven = 0, nOdd = 0;
    for (int i = 0; i <= splitInd; ++i) {
        int el = aArr[i];
        if (el % 2 == 0) {
            nEven++;
        } else {
            nOdd++;
        }
    }
    return nEven == nOdd;
}

int getMinAvailInd(const vector<int>& aArr, int nCoins, unordered_map<int, bool>& cutUsed) {
    int len = aArr.size();
    int minInd = -1;
    int minCost = nCoins + 1;
    for (int i = 1; i < len - 1; ++i) {
        int cost = abs(aArr[i] - aArr[i + 1]);
        if (cost < minCost) {
            if (checkSub(aArr, i)) {
                if (cutUsed.find(i) == cutUsed.end()) {
                    minCost = cost;
                    minInd = i;
                }
            }
        }
    }
    return minInd;
}

int getMaxCuts(int n, int b, const vector<int>& aArr) {
    int nCoins = b;
    int nCuts = 0;
    unordered_map<int, bool> cutUsed;
    while (nCoins > 0) {
        int ind = getMinAvailInd(aArr, nCoins, cutUsed);
        if (ind > -1) {
            cutUsed[ind] = true;
            int cost = abs(aArr[ind] - aArr[ind + 1]);
            nCoins -= cost;
            nCuts++;
        } else {
            break;
        }
    }
    return nCuts;
}

int main() {
    string nbLn, aLn;
    getline(cin, nbLn);
    getline(cin, aLn);
    vector<int> nbArr = strToIntArr(nbLn);
    vector<int> aArr = strToIntArr(aLn);
    int n = nbArr[0];
    int b = nbArr[1];
    int maxC = getMaxCuts(n, b, aArr);
    cout << maxC << "\n";
    return 0;
}

